-- A materialized view's _RETURN rule: pg_rewrite, pg_depend, rule DDL and ALTER TYPE.
CREATE TABLE t (a int, b text, c int);
INSERT INTO t VALUES (1, 'x', 2);
CREATE VIEW vv AS SELECT a, b FROM t WHERE a > 1;
CREATE MATERIALIZED VIEW mv AS SELECT a AS aa, b FROM t WHERE a > 1;
SELECT rulename, ev_type, ev_enabled, is_instead, ev_class::regclass FROM pg_rewrite WHERE ev_class = 'mv'::regclass;
SELECT pg_describe_object(classid, objid, objsubid) AS dependent, pg_describe_object(refclassid, refobjid, refobjsubid) AS referenced, deptype FROM pg_depend WHERE (refobjid = 't'::regclass OR refobjid = 'mv'::regclass) AND classid <> 'pg_class'::regclass ORDER BY 1, 2;
ALTER TABLE t ALTER COLUMN c TYPE bigint;
CREATE MATERIALIZED VIEW mvc AS SELECT c FROM t;
ALTER TABLE t ALTER COLUMN c TYPE int;
DROP MATERIALIZED VIEW mvc;
ALTER TABLE t ALTER COLUMN c TYPE int;
ALTER TABLE t ALTER COLUMN b TYPE varchar;
DROP VIEW vv;
ALTER TABLE t ALTER COLUMN b TYPE varchar;
ALTER TABLE t ALTER COLUMN a TYPE bigint;
SELECT pg_get_viewdef('mv'::regclass), pg_get_viewdef('mv'::regclass, true);
CREATE VIEW vv AS SELECT a, b FROM t WHERE a > 1;
SELECT pg_get_ruledef(oid), pg_get_ruledef(oid, true) FROM pg_rewrite WHERE ev_class IN ('vv'::regclass, 'mv'::regclass) ORDER BY ev_class::regclass::text;
SELECT definition FROM pg_matviews WHERE matviewname = 'mv';
SELECT pg_identify_object('pg_rewrite'::regclass, oid, 0), pg_identify_object_as_address('pg_rewrite'::regclass, oid, 0) FROM pg_rewrite WHERE ev_class = 'mv'::regclass;
DROP RULE "_RETURN" ON vv;
DROP RULE IF EXISTS "_RETURN" ON mv;
DROP RULE "_RETURN" ON mv CASCADE;
DROP RULE IF EXISTS r ON mv;
ALTER RULE "_RETURN" ON mv RENAME TO x;
ALTER RULE "_RETURN" ON vv RENAME TO x;
ALTER TABLE mv ENABLE RULE "_RETURN";
ALTER TABLE mv DISABLE TRIGGER ALL;
ALTER TABLE mv ENABLE REPLICA TRIGGER tg;
ALTER TABLE vv DISABLE RULE "_RETURN";
ALTER TABLE vv ENABLE ALWAYS RULE "_RETURN";
ALTER TABLE vv ENABLE TRIGGER USER;
CREATE RULE r AS ON INSERT TO mv DO INSTEAD NOTHING;
CREATE RULE r AS ON SELECT TO mv DO INSTEAD SELECT 1 AS a;
COMMENT ON RULE "_RETURN" ON vv IS 'view rule';
COMMENT ON RULE "_RETURN" ON mv IS 'materialized rule';
SELECT ev_class::regclass, obj_description(oid, 'pg_rewrite') FROM pg_rewrite WHERE ev_class IN ('vv'::regclass, 'mv'::regclass) ORDER BY 1;
DROP MATERIALIZED VIEW mv;
CREATE MATERIALIZED VIEW mv AS SELECT a FROM t;
SELECT obj_description(oid, 'pg_rewrite') FROM pg_rewrite WHERE ev_class = 'mv'::regclass;
CREATE VIEW v2 AS SELECT * FROM mv;
DROP TABLE t;
DROP TABLE t CASCADE;
